/**
 * CORRECAO - duas barras de rolagem na agenda (computador)
 *
 * O PROBLEMA
 *
 * No computador apareciam duas barras de rolagem: a da pagina e a da
 * propria agenda. Alem de confuso, a barra interna cortava o ultimo
 * horario do dia, obrigando a usar a outra barra para ver o final.
 *
 * A CORRECAO
 *
 * No computador a agenda deixa de ter rolagem propria - a pagina inteira
 * rola de uma vez so, com uma barra unica, e o ultimo horario aparece
 * completo.
 *
 * No CELULAR nada muda: la a rolagem interna continua, porque e ela que
 * mantem o cabecalho e a barra de baixo sempre visiveis.
 *
 * Tres funcionalidades dependiam dessa rolagem interna e foram adaptadas
 * para funcionar nos dois casos:
 *   - a rolagem automatica que abre a agenda ja no horario atual;
 *   - o botao "agora";
 *   - a deteccao de quando esse botao deve aparecer.
 *
 * Como usar: coloque este arquivo na RAIZ do projeto e rode
 *     node corrigir-rolagem-agenda.mjs
 *
 * E seguro rodar duas vezes: se ja estiver aplicado, ele avisa e pula.
 */

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { Buffer } from "node:buffer";

const ARQUIVO = "app/(app)/agenda/components/AgendaCalendar.tsx";

console.log("\nCorrecao - rolagem dupla na agenda\n");

if (!existsSync(ARQUIVO) || !existsSync("package.json")) {
  console.error("ERRO: nao encontrei o arquivo do projeto:\n");
  console.error("   " + ARQUIVO + "\n");
  console.error(
    "Coloque este script na pasta raiz do projeto (a mesma que tem o package.json) e rode de novo.\n",
  );
  process.exit(1);
}

